Cloud execution (reference)

Google Cloud Platform
// nextflow.config excerpt
profiles {
  gcp {
    process.executor = 'google-lifesciences'
    google {
      project = 'YOUR_PROJECT_ID'
      region  = 'us-central1'
      bucket = 'gs://your-nextflow-bucket'
    }
    workDir = 'gs://your-nextflow-bucket/work'
  }
}
nextflow run main.nf -profile gcp -with-report report.html


AWS Batch
profiles {
  aws {
    process.executor = 'awsbatch'
    aws.region = 'us-east-1'
    workDir = 's3://your-nextflow-bucket/work'
  }
}
nextflow run main.nf -profile aws -with-report report.html






Warning



Replace placeholder project IDs, buckets, and IAM roles with your organization’s approved cloud resources.



Back to home

Programs need to make decisions like a nurse: - IF patient temperature &gt; 38°C, THEN alert doctor - IF glucose &lt; 70 mg/dL, THEN give sugar tablet - IF medication available, THEN prescribe it



patient_temp &lt;- 39.2  # Celsius

if (patient_temp &gt; 38.5) {
  print("ALERT: Fever detected! Notify physician!")
} else if (patient_temp &gt; 37.5) {
  print("WARNING: Slight elevation. Monitor closely.")
} else {
  print("Normal temperature.")
}

# Output: "ALERT: Fever detected! Notify physician!"



# Diabetes risk assessment
age &lt;- 52
fasting_glucose &lt;- 245
family_history &lt;- TRUE

if (fasting_glucose &gt; 200 & age &gt; 45) {
  risk &lt;- "High"
} else if (fasting_glucose &gt; 150) {
  risk &lt;- "Moderate"
} else {
  risk &lt;- "Low"
}

print(paste("Risk level:", risk))
# Output: "Risk level: High"



# Lab test result classification
test_result &lt;- 8.5  # Hemoglobin g/dL

if (test_result &lt; 7) {
  severity &lt;- "Critical"
} else if (test_result &lt; 8) {
  severity &lt;- "Severe"
} else if (test_result &lt; 10) {
  severity &lt;- "Moderate"
} else if (test_result &lt; 12) {
  severity &lt;- "Mild"
} else {
  severity &lt;- "Normal"
}

# OR use switch with intervals:
get_severity &lt;- function(hgb) {
  if (hgb &lt; 7) return("Critical")
  if (hgb &lt; 8) return("Severe")
  if (hgb &lt; 10) return("Moderate")
  if (hgb &lt; 12) return("Mild")
  return("Normal")
}

print(get_severity(8.5))  # "Moderate"

A loop is like reading a checklist: - “Check blood pressure for patient 1” - “Check blood pressure for patient 2” - …repeat for all 100 patients



You need to check 5 patients’ lab results:
# WITHOUT loop (tedious)
glucose_1 &lt;- 245
status_1 &lt;- if (glucose_1 &gt; 200) "At Risk" else "Normal"

glucose_2 &lt;- 198
status_2 &lt;- if (glucose_2 &gt; 200) "At Risk" else "Normal"

glucose_3 &lt;- 310
status_3 &lt;- if (glucose_3 &gt; 200) "At Risk" else "Normal"
# ... repeat 47 more times for 50 patients!

# WITH loop (clean)
glucose_readings &lt;- c(245, 198, 310, 185, 225)

for (glucose in glucose_readings) {
  if (glucose &gt; 200) {
    print(paste("Glucose:", glucose, "→ AT RISK"))
  } else {
    print(paste("Glucose:", glucose, "→ Normal"))
  }
}

# Output:
# Glucose: 245 → AT RISK
# Glucose: 198 → Normal
# Glucose: 310 → AT RISK
# Glucose: 185 → Normal
# Glucose: 225 → AT RISK



# Check all patients in a clinical trial
trial &lt;- data.frame(
  patient = c("P001", "P002", "P003"),
  bmi = c(24.5, 32.1, 26.8)
)

for (i in 1:nrow(trial)) {
  patient_id &lt;- trial[i, "patient"]
  bmi_value &lt;- trial[i, "bmi"]

  if (bmi_value &gt; 30) {
    print(paste(patient_id, "is obese (BMI =", bmi_value, ")"))
  } else {
    print(paste(patient_id, "is normal (BMI =", bmi_value, ")"))
  }
}

# Output:
# P001 is normal (BMI = 24.5 )
# P002 is obese (BMI = 32.1 )
# P003 is normal (BMI = 26.8 )
